"""Commands added so the product works over the CLI and web app (generated by _tools/add_commands.py)."""

import contextlib
import io
import json
import pathlib
import tempfile
import unittest

from grantgate.__main__ import main

EX = pathlib.Path(__file__).resolve().parent.parent / "examples"


class CommandTests(unittest.TestCase):
    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)

    def write(self, obj) -> str:
        path = pathlib.Path(self.tmp.name) / "req.json"
        path.write_text(json.dumps(obj), encoding="utf-8")
        return str(path)

    def run_cli(self, argv):
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            code = main(argv)
        self.assertIn(code, (0, 1), out.getvalue())
        return json.loads(out.getvalue())

    def test_within_caps_to_approved_payee_is_allowed(self):
        out = self.run_cli(
            ["check", str(EX / "bank-grant.json"), "--op", "transfer", "--amount", "20", "--payee", "ConEd"]
        )
        self.assertTrue(out["allowed"])

    def test_total_cap_and_unapproved_payee_are_denied(self):
        over = self.run_cli(
            ["check", str(EX / "bank-grant.json"), "--op", "transfer", "--amount", "40", "--payee", "ConEd"]
        )
        self.assertIn("total cap", over["reason"])
        mallory = self.run_cli(
            ["check", str(EX / "bank-grant.json"), "--op", "transfer", "--amount", "5", "--payee", "Mallory"]
        )
        self.assertIn("not approved", mallory["reason"])


if __name__ == "__main__":
    unittest.main()
